import { BrowserRouter, Routes, Route, NavLink, useNavigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import ProtectedRoute from './components/ProtectedRoute';
import LoginPage from './pages/LoginPage';
import ProjectsPage from './pages/ProjectsPage';
import ReportsPage from './pages/ReportsPage';
import SyncPage from './pages/SyncPage';
import UsersPage from './pages/UsersPage';

function Nav() {
  const { user, logout, canEdit, canManageUsers } = useAuth();
  const navigate = useNavigate();
  if (!user) return null;

  return (
    <nav style={{ display: 'flex', alignItems: 'center', gap: 16, padding: '12px 24px', borderBottom: '1px solid #e0e0e0', background: '#fff' }}>
      <strong>AccessParks Asana App</strong>
      <Link to="/">Projects</Link>
      <Link to="/reports">Reports</Link>
      {canEdit && <Link to="/sync">Sync</Link>}
      {canManageUsers && <Link to="/users">Users</Link>}
      <span style={{ marginLeft: 'auto', fontSize: 13, color: '#555' }}>
        {user.fullName || user.email} ({user.role})
      </span>
      <button onClick={() => { logout(); navigate('/login'); }}>Log out</button>
    </nav>
  );
}

export default function App() {
  return (
    <AuthProvider>
      <BrowserRouter>
        <Nav />
        <Routes>
          <Route path="/login" element={<LoginPage />} />
          <Route path="/" element={<ProtectedRoute><ProjectsPage /></ProtectedRoute>} />
          <Route path="/reports" element={<ProtectedRoute><ReportsPage /></ProtectedRoute>} />
          <Route path="/sync" element={
            <ProtectedRoute require={(auth) => auth.canEdit}><SyncPage /></ProtectedRoute>
          } />
          <Route path="/users" element={
            <ProtectedRoute require={(auth) => auth.canManageUsers}><UsersPage /></ProtectedRoute>
          } />
        </Routes>
      </BrowserRouter>
    </AuthProvider>
  );
}
